estilos.css:
.home-intro {
  padding: 2px 2px 4px;
}
.home-eyebrow {
  display:block;
  margin-bottom:6px;
  color:var(--gold);
  font-size:11px;
  font-weight:900;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.home-intro h1 {
  margin:0;
  color:var(--primary);
  font-size:24px;
  line-height:1.15;
  letter-spacing:-.025em;
}
.home-intro p {
  max-width:560px;
  margin:8px 0 0;
  color:var(--muted);
  font-size:14px;
  line-height:1.5;
}
